    method: 'post', contentType: 'application/json', muteHttpExceptions: true,
    payload: JSON.stringify({ contents: [{ parts: [{ text: prompt }] }], generationConfig: { temperature: suhu == null ? 0.7 : suhu, maxOutputTokens: 2048, responseMimeType: 'application/json' } }) });
  var kode = r.getResponseCode(), isi = r.getContentText();
